head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[linkedDataList > M > getAllXML]<br/>LinkedDataList 모듈에 링크된 전체 Row 데이터를 XML 객체로 반환합니다.",
    "validation" : [
        "'Filter Condition' 이 적용되고, 필터/정렬이 적용되지 않은 상태를 기준으로 동작합니다.",
        "반환값으로 Row 의 상태값에 관계없이 전체 Row 의 데이터를 XML 객체로 반환합니다.",
        "XML 은 인덱스값이 작은 Row 부터 큰 Row 순서로 생성됩니다.",
        "반환된 객체의 xml 속성값으로 Root 노드의 태그명으로 'list' 가 적용되고, 반복되는 데이터 노드의 태그엔 'map' 이 적용됩니다.",
        "데이터 노드는 index 속성으로 필터가 적용되지 않은 원본 DataList 모듈의 Row 인덱스값이 설정됩니다.",
        "데이터 노드의 하위 노드로 LinkedDataList 모듈의 Column ID 와 Column 값이 반복됩니다.",
        "데이터 노드는 'rowStatus' 를 마지막 하위 태그로 Row 의 상태값이 설정되며 'statusValue' 속성으로 상태코드값이 설정됩니다.",
        "getAllXML() 메소드는 링크된 원본 DataList 모듈에 필터가 적용된 기준으로 Row 데이터를 반환합니다.",
        "원본 DataLIst 모듈이 rowNumData=true 인 경우 반환값의 마지막 Key 로 'rowNum' 이 추가되고 Row 의 순번(인덱스+1)값을 갖습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
	// 기존 target 있으면 삭제
    if (typeof gdl_org !== 'undefined') {
        $p.data.remove("gdl_org");
    }

    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }   

    if (typeof gridView2 !== 'undefined') {
        gridView2.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

	// target 생성
    $c.gcm.createOrginalDataList('rowNumData="true"');
    $c.gcm.createBasicLinkedDataList();

    // gridView 생성
    $c.gcm.createOriginalGridView();
    $c.gcm.createLinkedGridView();
}   



scwin.btn_getAllXML_onclick = function (e) {
    let rtn = target1.getAllXML();
    const serializer = new XMLSerializer();
    let xmlString = serializer.serializeToString(rtn);

	wf_body_bottom.getObj("scwin").setReturnValue("result: " + rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("result.xml: " + xmlString);
};



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter({type:"row", colIndex:"cat2", key:"A1", condition:"and"});
};



scwin.btn_org_setColumnFilter_onclick = function (e) {
	gdl_org.setColumnFilter({type:"row", colIndex:"value", key:"AA11", condition:"and"});
    gdl_org.setColumnFilter({type:"row", colIndex:"value", key:"AA21", condition:"or"});
    gdl_org.setColumnFilter({type:"row", colIndex:"value", key:"BB11", condition:"or"});
    gdl_org.setColumnFilter({type:"row", colIndex:"value", key:"BB21", condition:"or"});
};
